import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BiXHgXAn.js";const f=JSON.parse('{"title":"Environment Reference","description":"A reference for the Taskfile environment variables","frontmatter":{"title":"Environment Reference","description":"A reference for the Taskfile environment variables","section":"Reference","docType":"reference","outline":"deep"},"headers":[],"relativePath":"docs/reference/environment.md","filePath":"next/docs/reference/environment.md"}'),i={name:"docs/reference/environment.md"};function d(c,e,l,s,n,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="environment-reference" tabindex="-1">Environment Reference <a class="header-anchor" href="#environment-reference" aria-label="Permalink to &quot;Environment Reference&quot;">​</a></h1><p>Task has multiple ways of being configured. These methods are parsed, in sequence, in the following order with the highest priority last:</p><ul><li><a href="./config">Configuration files</a></li><li><em>Environment variables</em></li><li><a href="./cli">Command-line flags</a></li></ul><p>In this document, we will look at the second of the three options, environment variables. All Task-specific variables are prefixed with <code>TASK_</code> and override their configuration file equivalents.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>All <a href="./config">configuration file options</a> can also be set via environment variables. The priority order is: CLI flags &gt; environment variables &gt; config files &gt; defaults.</p><h3 id="task-verbose" tabindex="-1"><code>TASK_VERBOSE</code> <a class="header-anchor" href="#task-verbose" aria-label="Permalink to &quot;`TASK_VERBOSE`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Enable verbose output for all tasks</li><li><strong>Config equivalent</strong>: <a href="./config#verbose"><code>verbose</code></a></li></ul><h3 id="task-silent" tabindex="-1"><code>TASK_SILENT</code> <a class="header-anchor" href="#task-silent" aria-label="Permalink to &quot;`TASK_SILENT`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Disables echoing of commands</li><li><strong>Config equivalent</strong>: <a href="./config#silent"><code>silent</code></a></li></ul><h3 id="task-color" tabindex="-1"><code>TASK_COLOR</code> <a class="header-anchor" href="#task-color" aria-label="Permalink to &quot;`TASK_COLOR`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>true</code></li><li><strong>Description</strong>: Enable colored output</li><li><strong>Config equivalent</strong>: <a href="./config#color"><code>color</code></a></li></ul><h3 id="task-disable-fuzzy" tabindex="-1"><code>TASK_DISABLE_FUZZY</code> <a class="header-anchor" href="#task-disable-fuzzy" aria-label="Permalink to &quot;`TASK_DISABLE_FUZZY`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Disable fuzzy matching for task names</li><li><strong>Config equivalent</strong>: <a href="./config#disable-fuzzy"><code>disable-fuzzy</code></a></li></ul><h3 id="task-concurrency" tabindex="-1"><code>TASK_CONCURRENCY</code> <a class="header-anchor" href="#task-concurrency" aria-label="Permalink to &quot;`TASK_CONCURRENCY`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>integer</code></li><li><strong>Description</strong>: Limit number of tasks to run concurrently</li><li><strong>Config equivalent</strong>: <a href="./config#concurrency"><code>concurrency</code></a></li></ul><h3 id="task-failfast" tabindex="-1"><code>TASK_FAILFAST</code> <a class="header-anchor" href="#task-failfast" aria-label="Permalink to &quot;`TASK_FAILFAST`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: When running tasks in parallel, stop all tasks if one fails</li><li><strong>Config equivalent</strong>: <a href="./config#failfast"><code>failfast</code></a></li></ul><h3 id="task-dry" tabindex="-1"><code>TASK_DRY</code> <a class="header-anchor" href="#task-dry" aria-label="Permalink to &quot;`TASK_DRY`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Compiles and prints tasks in the order that they would be run, without executing them</li></ul><h3 id="task-assume-yes" tabindex="-1"><code>TASK_ASSUME_YES</code> <a class="header-anchor" href="#task-assume-yes" aria-label="Permalink to &quot;`TASK_ASSUME_YES`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Assume &quot;yes&quot; as answer to all prompts</li></ul><h3 id="task-interactive" tabindex="-1"><code>TASK_INTERACTIVE</code> <a class="header-anchor" href="#task-interactive" aria-label="Permalink to &quot;`TASK_INTERACTIVE`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Prompt for missing required variables</li></ul><h3 id="task-output" tabindex="-1"><code>TASK_OUTPUT</code> <a class="header-anchor" href="#task-output" aria-label="Permalink to &quot;`TASK_OUTPUT`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>string</code> (<code>interleaved</code>, <code>group</code>, <code>prefixed</code>)</li><li><strong>Description</strong>: Sets the output style</li><li><strong>CLI equivalent</strong>: <a href="./cli#o-output-mode"><code>--output</code></a></li></ul><h3 id="task-output-group-begin" tabindex="-1"><code>TASK_OUTPUT_GROUP_BEGIN</code> <a class="header-anchor" href="#task-output-group-begin" aria-label="Permalink to &quot;`TASK_OUTPUT_GROUP_BEGIN`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>string</code></li><li><strong>Description</strong>: Message template to print before a task&#39;s grouped output. Only applies when the output style is <code>group</code>.</li><li><strong>CLI equivalent</strong>: <a href="./cli#output-group-begin-template"><code>--output-group-begin</code></a></li></ul><h3 id="task-output-group-end" tabindex="-1"><code>TASK_OUTPUT_GROUP_END</code> <a class="header-anchor" href="#task-output-group-end" aria-label="Permalink to &quot;`TASK_OUTPUT_GROUP_END`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>string</code></li><li><strong>Description</strong>: Message template to print after a task&#39;s grouped output. Only applies when the output style is <code>group</code>.</li><li><strong>CLI equivalent</strong>: <a href="./cli#output-group-end-template"><code>--output-group-end</code></a></li></ul><h3 id="task-output-group-error-only" tabindex="-1"><code>TASK_OUTPUT_GROUP_ERROR_ONLY</code> <a class="header-anchor" href="#task-output-group-error-only" aria-label="Permalink to &quot;`TASK_OUTPUT_GROUP_ERROR_ONLY`&quot;">​</a></h3><ul><li><strong>Type</strong>: <code>boolean</code> (<code>true</code>, <code>false</code>, <code>1</code>, <code>0</code>)</li><li><strong>Default</strong>: <code>false</code></li><li><strong>Description</strong>: Swallow output from successful tasks. Only applies when the output style is <code>group</code>.</li><li><strong>CLI equivalent</strong>: <a href="./cli#output-group-error-only"><code>--output-group-error-only</code></a></li></ul><h3 id="task-temp-dir" tabindex="-1"><code>TASK_TEMP_DIR</code> <a class="header-anchor" href="#task-temp-dir" aria-label="Permalink to &quot;`TASK_TEMP_DIR`&quot;">​</a></h3><p>Defines the location of Task&#39;s temporary directory which is used for storing checksums and temporary metadata. Can be relative like <code>tmp/task</code> or absolute like <code>/tmp/.task</code> or <code>~/.task</code>. Relative paths are relative to the root Taskfile, not the working directory. Defaults to: <code>./.task</code>.</p><h3 id="task-core-utils" tabindex="-1"><code>TASK_CORE_UTILS</code> <a class="header-anchor" href="#task-core-utils" aria-label="Permalink to &quot;`TASK_CORE_UTILS`&quot;">​</a></h3><p>This env controls whether the Bash interpreter will use its own core utilities implemented in Go, or the ones available in the system. Valid values are <code>true</code> (<code>1</code>) or <code>false</code> (<code>0</code>). By default, this is <code>true</code> on Windows and <code>false</code> on other operating systems. We might consider making this enabled by default on all platforms in the future.</p><h3 id="force-color" tabindex="-1"><code>FORCE_COLOR</code> <a class="header-anchor" href="#force-color" aria-label="Permalink to &quot;`FORCE_COLOR`&quot;">​</a></h3><p>Force color output usage.</p><h2 id="remote-taskfile-variables" tabindex="-1">Remote Taskfile Variables <a class="header-anchor" href="#remote-taskfile-variables" aria-label="Permalink to &quot;Remote Taskfile Variables&quot;">​</a></h2><p>The following variables are used to control the behavior of <a href="./../remote-taskfiles">remote Taskfiles</a>.</p><h3 id="task-remote-insecure" tabindex="-1"><code>TASK_REMOTE_INSECURE</code> <a class="header-anchor" href="#task-remote-insecure" aria-label="Permalink to &quot;`TASK_REMOTE_INSECURE`&quot;">​</a></h3><p>Allow insecure connections when fetching remote Taskfiles.</p><h3 id="task-remote-offline" tabindex="-1"><code>TASK_REMOTE_OFFLINE</code> <a class="header-anchor" href="#task-remote-offline" aria-label="Permalink to &quot;`TASK_REMOTE_OFFLINE`&quot;">​</a></h3><p>Work in offline mode, preventing remote Taskfile fetching.</p><h3 id="task-remote-timeout" tabindex="-1"><code>TASK_REMOTE_TIMEOUT</code> <a class="header-anchor" href="#task-remote-timeout" aria-label="Permalink to &quot;`TASK_REMOTE_TIMEOUT`&quot;">​</a></h3><p>Timeout duration for remote operations (e.g., &#39;30s&#39;, &#39;5m&#39;).</p><h3 id="task-remote-cache-expiry" tabindex="-1"><code>TASK_REMOTE_CACHE_EXPIRY</code> <a class="header-anchor" href="#task-remote-cache-expiry" aria-label="Permalink to &quot;`TASK_REMOTE_CACHE_EXPIRY`&quot;">​</a></h3><p>Cache expiry duration for remote Taskfiles (e.g., &#39;1h&#39;, &#39;24h&#39;).</p><h3 id="task-remote-cache-dir" tabindex="-1"><code>TASK_REMOTE_CACHE_DIR</code> <a class="header-anchor" href="#task-remote-cache-dir" aria-label="Permalink to &quot;`TASK_REMOTE_CACHE_DIR`&quot;">​</a></h3><p>Directory where remote Taskfiles are cached. Can be an absolute path (e.g., <code>/var/cache/task</code>) or relative to the Taskfile directory.</p><h3 id="task-remote-trusted-hosts" tabindex="-1"><code>TASK_REMOTE_TRUSTED_HOSTS</code> <a class="header-anchor" href="#task-remote-trusted-hosts" aria-label="Permalink to &quot;`TASK_REMOTE_TRUSTED_HOSTS`&quot;">​</a></h3><p>List of (comma-separated) trusted hosts for remote Taskfiles. Hosts in this list will not prompt for confirmation when downloading Taskfiles.</p><p>Hosts in the trusted hosts list will automatically be trusted without prompting for confirmation when they are first downloaded or when their checksums change. The host matching includes the port if specified in the URL. Use with caution and only add hosts you fully trust.</p><h3 id="task-remote-cacert" tabindex="-1"><code>TASK_REMOTE_CACERT</code> <a class="header-anchor" href="#task-remote-cacert" aria-label="Permalink to &quot;`TASK_REMOTE_CACERT`&quot;">​</a></h3><p>Path to a custom CA certificate file for TLS verification.</p><h3 id="task-remote-cert" tabindex="-1"><code>TASK_REMOTE_CERT</code> <a class="header-anchor" href="#task-remote-cert" aria-label="Permalink to &quot;`TASK_REMOTE_CERT`&quot;">​</a></h3><p>Path to a client certificate file for mTLS authentication.</p><h3 id="task-remote-cert-key" tabindex="-1"><code>TASK_REMOTE_CERT_KEY</code> <a class="header-anchor" href="#task-remote-cert-key" aria-label="Permalink to &quot;`TASK_REMOTE_CERT_KEY`&quot;">​</a></h3><p>Path to the client certificate private key file.</p><h3 id="custom-colors" tabindex="-1">Custom Colors <a class="header-anchor" href="#custom-colors" aria-label="Permalink to &quot;Custom Colors&quot;">​</a></h3><p>All color variables are <a href="https://en.wikipedia.org/wiki/ANSI_escape_code" target="_blank" rel="noreferrer">ANSI color codes</a>. You can specify multiple codes separated by a semicolon. For example: <code>31;1</code> will make the text bold and red. Task also supports 8-bit color (256 colors). You can specify these colors by using the sequence <code>38;2;R:G:B</code> for foreground colors and <code>48;2;R:G:B</code> for background colors where <code>R</code>, <code>G</code> and <code>B</code> should be replaced with values between 0 and 255.</p><p>For convenience, we allow foreground colors to be specified using shorthand, comma-separated syntax: <code>R,G,B</code>. For example, <code>255,0,0</code> is equivalent to <code>38;2;255:0:0</code>.</p><p>A table of variables and their defaults can be found below:</p><table tabindex="0"><thead><tr><th>ENV</th><th>Default</th></tr></thead><tbody><tr><td><code>TASK_COLOR_RESET</code></td><td><code>0</code></td></tr><tr><td><code>TASK_COLOR_RED</code></td><td><code>31</code></td></tr><tr><td><code>TASK_COLOR_GREEN</code></td><td><code>32</code></td></tr><tr><td><code>TASK_COLOR_YELLOW</code></td><td><code>33</code></td></tr><tr><td><code>TASK_COLOR_BLUE</code></td><td><code>34</code></td></tr><tr><td><code>TASK_COLOR_MAGENTA</code></td><td><code>35</code></td></tr><tr><td><code>TASK_COLOR_CYAN</code></td><td><code>36</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_RED</code></td><td><code>91</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_GREEN</code></td><td><code>92</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_YELLOW</code></td><td><code>93</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_BLUE</code></td><td><code>94</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_MAGENTA</code></td><td><code>95</code></td></tr><tr><td><code>TASK_COLOR_BRIGHT_CYAN</code></td><td><code>96</code></td></tr></tbody></table>',64)])])}const p=o(i,[["render",d]]);export{f as __pageData,p as default};
